begin;
select set_config('rdr.a',gen_random_uuid()::text,true),set_config('rdr.b',gen_random_uuid()::text,true),set_config('rdr.p',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('rdr.a')::uuid,'reorder-a@example.invalid'),(current_setting('rdr.b')::uuid,'reorder-b@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('rdr.a'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,barcode,sale_price,reorder_units) values(current_setting('rdr.p')::uuid,'Boundary','00123',1500,2501);
insert into public.products(name,sale_price,reorder_units) values('Zero',1,0),('Below',1,2500),('Above',1,2500),('Unset',1,null);
select public.post_purchase(gen_random_uuid(),(select jsonb_agg(jsonb_build_object('product_id',id,'quantity_units',case name when 'Boundary' then 2501 when 'Below' then 1000 else 5000 end,'unit_cost',1)) from public.products where name in ('Boundary','Below','Above')),'','','');
do $$declare n bigint;v jsonb;begin
 if (select count(*) from public.low_stock_catalog)<>3 then raise exception 'threshold filter wrong';end if;
 if not exists(select 1 from public.low_stock_catalog where name='Boundary' and quantity_units=2501 and reorder_units=2501) then raise exception 'inclusive fractional boundary wrong';end if;
 if not exists(select 1 from public.low_stock_catalog where name='Zero' and quantity_units=0 and reorder_units=0) then raise exception 'missing stock is not zero';end if;
 if exists(select 1 from public.low_stock_catalog where name in ('Above','Unset')) then raise exception 'above or unset included';end if;
 select count(*) into n from public.stock_movements;
 begin update public.products set reorder_units=-1 where id=current_setting('rdr.p')::uuid;raise exception 'negative allowed';exception when check_violation then null;end;
 begin update public.products set reorder_units=1000000000001 where id=current_setting('rdr.p')::uuid;raise exception 'too large allowed';exception when check_violation then null;end;
 update public.products set reorder_units=1000000000000 where id=current_setting('rdr.p')::uuid;
 if not exists(select 1 from public.low_stock_catalog where id=current_setting('rdr.p')::uuid and reorder_units=1000000000000) then raise exception 'maximum lost';end if;
 v:=public.export_owner_data();if not exists(select 1 from jsonb_array_elements(v#>'{tables,products}') r where r->>'id'=current_setting('rdr.p') and r->>'reorder_units'='1000000000000') then raise exception 'export omitted threshold';end if;
 update public.products set reorder_units=null where id=current_setting('rdr.p')::uuid;
 if exists(select 1 from public.low_stock_catalog where id=current_setting('rdr.p')::uuid) then raise exception 'clear failed';end if;
 if (select count(*) from public.stock_movements)<>n then raise exception 'threshold changed stock';end if;
 if has_table_privilege('authenticated','public.low_stock_catalog','insert') or has_table_privilege('authenticated','public.low_stock_catalog','update') or has_table_privilege('authenticated','public.low_stock_catalog','delete') then raise exception 'view is writable';end if;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rdr.b'),'role','authenticated')::text,true);set local role authenticated;
do $$declare n bigint;begin if (select count(*) from public.low_stock_catalog)<>0 then raise exception 'other owner leaked';end if;update public.products set reorder_units=1 where id=current_setting('rdr.p')::uuid;get diagnostics n=row_count;if n<>0 then raise exception 'other owner updated';end if;end $$;
insert into public.products(name,sale_price,reorder_units) select 'Page '||g,1,0 from generate_series(1,51) g;
do $$begin if (select count(*) from public.low_stock_catalog)<>51 or (select count(*) from (select id from public.low_stock_catalog order by quantity_units,name,id limit 50 offset 50) x)<>1 then raise exception 'owner count or page wrong';end if;end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin if exists(select 1 from public.low_stock_catalog) then raise exception 'missing UID leaked';end if;end $$;
reset role;set local role anon;
do $$begin begin perform 1 from public.low_stock_catalog;raise exception 'anonymous allowed';exception when insufficient_privilege then null;end;end $$;
reset role;select 'PASS: nullable/exact minimum, inclusive threshold, missing stock, limits, export, no stock mutation, read-only view, pagination and owner/anonymous isolation' verification;
rollback;
